const OPTION_IDS = ['A', 'B', 'C', 'D'] as const

export const CPE301_QUESTIONS: CbtQuestion[] = RAW_CPE_QUESTIONS.map(
  ([num, topic, topicName, partName, sectionName, question, opts, answer, passage]) => {
    const answerIdx = OPTION_IDS.indexOf(answer)
    const correctText = opts[answerIdx] ?? ''
    return {
      id: `cpe-q${num}`,
      subjectCode: 'CPE-301',
      subjectName: 'Cleaner Production & Circular Economy',
      semester: 7,
      category: 'open-elective',
      topic,
      topicName,
      partName,
      sectionName,
      ...(passage ? { passage } : {}),
      question,
      type: 'single',
      options: OPTION_IDS.map((id, idx) => ({ id, text: opts[idx] })),
      correctAnswers: [answer],
      explanation: `Correct Answer: (${answer}) ${correctText}.`,
      difficulty: 'medium',
      status: 'approved'
    }
  }
)
